"use strict";(self.webpackChunkfansite_reol=self.webpackChunkfansite_reol||[]).push([[5129],{74114:function(n,e,o){function t(n){const e=n.split("\n"),o=[];let t=0;const a=n=>{if(n.length>0){const e=n.join("\n").trim();e&&o.push({type:"text",content:e}),n.length=0}},i=[];for(;t<e.length;){const n=e[t];if(""===n.trim()){a(i),t++;continue}if(/^-{3,}$/.test(n.trim())){a(i),o.push({type:"divider"}),t++;continue}if(/^#### /.test(n)){a(i),o.push({type:"heading",content:n.replace(/^#### /,"").trim(),level:4}),t++;continue}if(/^### /.test(n)){a(i),o.push({type:"heading",content:n.replace(/^### /,"").trim(),level:3}),t++;continue}if(/^## /.test(n)){a(i),o.push({type:"heading",content:n.replace(/^## /,"").trim(),level:2}),t++;continue}if(/^> /.test(n)){a(i);const n=[];for(;t<e.length&&/^> /.test(e[t]);)n.push(e[t].replace(/^> /,"")),t++;o.push({type:"quote",content:n.join("\n").trim()});continue}if(/^[-*] /.test(n)){a(i);const n=[];for(;t<e.length&&(/^[-*] /.test(e[t])||/^\s+[-*] /.test(e[t]));){if(/^[-*] /.test(e[t]))n.push({text:e[t].replace(/^[-*] /,"").trim()});else if(/^\s+[-*] /.test(e[t])&&n.length>0){const o=n[n.length-1];o.subItems||(o.subItems=[]),o.subItems.push(e[t].replace(/^\s+[-*] /,"").trim())}t++}o.push({type:"list",items:n});continue}const s=n.match(/^\[map:([^\]]+)\]\(([^)]+)\)$/);if(s){a(i),o.push({type:"map",mapTitle:s[1].trim(),mapUrl:s[2].trim()}),t++;continue}const r=n.match(/^!\[([^\]]*)\]\(([^)"]+)(?:\s+"([^"]*)")?\)$/);r?(a(i),o.push({type:"image",alt:r[1]||void 0,src:r[2],caption:r[3]||void 0}),t++):(i.push(n),t++)}return a(i),o}o.d(e,{K7:function(){return i},Bi:function(){return a},l6:function(){return s}});const a={analysis:{ja:"考察・分析",en:"Analysis",emoji:"🔍",color:"purple"},"venue-guide":{ja:"会場ガイド",en:"Venue Guide",emoji:"🏟️",color:"blue"},column:{ja:"コラム",en:"Column",emoji:"✍️",color:"amber"},tips:{ja:"ライヴTips",en:"Live Tips",emoji:"💡",color:"green"}};const i=[{slug:"live-tips-first-timer",title:"Reolライヴ はじめてガイド",titleEn:"Your First Reol Concert — Starter Guide",subtitle:"持ち物・服装・マナーまでまるごと紹介",subtitleEn:"What to bring, what to wear, and concert etiquette",category:"tips",tags:["ライヴ","初心者","持ち物","マナー"],tagsEn:["Live","Beginner","Essentials","Etiquette"],author:"美辞学ナビ編集部",authorEn:"Bijigaku Navi Editorial",publishedAt:"2026-02-19T00:00:00+09:00",emoji:"🎤",readingTime:8,sections:[],markdownFile:"「美辞学ツアーが初ライヴ！」という方も多いのではないでしょうか。\nここでは、Reolのライヴに行く前に知っておきたい情報をまとめました。\nもちろん、ライヴの楽しみ方は十人十色なので、この記事はあくまで参考程度に読んでもらえると嬉しいです。\n\n## 持ち物チェックリスト（入場時）\n\n#### 必須\n\n- 🎫 チケット\n  - 電子チケットのためスマホの充電を温存しておこう\n- 💰 現金\n  - ドリンクチケット用。入場時に600円程度必要な場合が多い\n  - キャッシュレスに対応していない会場もあるため事前に確認しておこう\n- 💧 飲み物\n  - 入場時に引き換えるドリンクチケットとドリンクを交換できる\n  - 叫んだり汗をかくと喉が渇くので必須\n  - とにかく前に行きたい人は事前に飲み物を買っておいて、ライヴ終わりに引き換えるのがおすすめ\n\n#### あると便利\n\n- 🔒 小さめバッグ\n  - 邪魔にならないサイズのもの\n- 🎤 タオル\n  - 汗拭き用。Reolのライヴはエクササイズくらい熱くなる\n- 👂 耳栓\n  - ライヴ用イヤープロテクターがおすすめ\n  - 音響外傷で難聴になることがあるので、心配な人には推奨\n- 👟 履き慣れたスニーカー\n  - スタンディングの場合は特に重要\n\n#### 不要\n\n- 🧳 大きなバッグ\n  - ロッカーに入らない、周囲の人の迷惑になるのでホテルに置いてこよう\n- 🔋 モバイルバッテリー\n  - 静かに見る人ならあっても良いが、飛ぶには重すぎるのでロッカーに入れておこう\n\n## 服装のポイント\n\nスタンディングの場合は動きやすい服装が基本。ホール公演ではもう少しラフでも大丈夫ですが、いずれにしても以下がポイントです。\n\n- 厚底・ヒールの高い靴は避ける\n  - 周囲の方への配慮＋自分の安全のため\n  - 身長が低い方は、厚底もありだが怪我などには注意\n- 大きなアクセサリー・帽子は外す\n  - 後ろの方が見えなくなります\n- 会場内は暑くなることが多い\n  - 脱ぎ着しやすい重ね着が◎\n- 荷物はコインロッカーに預けて身軽に\n  - 大きな荷物はスタッフから注意されることもある\n\n## スタンディングの立ち位置\n\nスタンディングの場合、チケットの整理番号順に入場した後は立ち位置を自分の好みで決められるため、どこで見るかで体験が大きく変わります。前方の空きスペースを見つけて詰めるなり、あえて後ろに下がるなり、自分の楽しみ方に合った場所を選びましょう。\n\nまた、会場によっては建物構造上、大きな柱などがあり見えにくい場所や音が届きにくい場所があることもありますので、事前に会場レイアウトを確認しておくと安心です。\n\n- **前方中央エリア**\n  - アーティストとの距離が近く臨場感が抜群\n  - Reolの表情や細かい演出も見たい方におすすめ\n  - 人が密集しやすく、押されたり揉まれたりすることがある\n  - ライヴ慣れしている人の中には、少しでも空いているスペースがあれば空けておいた空間に入ってくることもあるので、譲りたくない場合は詰めるか死守しましょう（話せばわかるきっと…喧嘩だけはしないでね）\n  - 体力に自信がある人向け\n- **中間〜後方エリア**\n  - 比較的ゆったり楽しめる\n  - ステージ全体の演出や照明を見渡せる\n  - 初めてのライヴにはおすすめ\n- **左右のエリア**\n  - 比較的空いていて整理番号が遅くても前方に行きやすい\n  - バンドメンバーの演奏を近くで見たい方におすすめ\n  - 角度によってはステージが見えにくいことも\n  - スピーカーの目の前で音が大きいことがあるので注意\n- **（ある場合）2F席**\n  - 視界が広く、ステージ全体を見渡せる\n  - 音響のバランスが良いことが多い\n  - スタンディングエリアよりもアーティストとの距離があるため、表情や細かい演出は見えにくいことも\n\n## コインロッカー事情\n\n各会場の詳細ページにコインロッカー情報をまとめています。ライヴハウスの場合、会場内にロッカーがあることも。ホール公演ではクロークが用意されることもあります。会場周辺のコインロッカーを事前にチェックしておくと安心です。\n\n## ライヴ中のマナー\n\n- 📱 撮影・録音は禁止\n  - 公式アナウンスがある場合を除く\n- 🗣 MC中や静かなパートでは周囲に配慮\n- 🎶 アーティストから煽られた場合以外、日本では一緒に歌うのは周囲の迷惑になりがち\n  - 国によっては一緒に歌う文化もあるので、郷に従おう\n- 🙋 モッシュ・ダイブは原則禁止\n- 🎒 大きな荷物は必ずロッカーへ\n- 🤝 周囲のファンと協力して楽しい空間を作ろう\n\n## ライヴの楽しみ方\n\n楽しみ方は人それぞれ。自分のペースで、好きなように楽しむのが一番です。\n\n以下は一例ですが、参考にしてみてください。\n\n- 💡 迷惑にならない限りは、自分の好きなスタイルで楽しむのが一番！（無理して合わせる必要はありません）\n- 🎤 アーティストとの一体感を楽しむ\n- 🎶 演出や照明、音響を堪能する\n- 🕺 周りのファンと一緒に盛り上がる\n- 📸 (撮影可能の場合)グッズや会場の雰囲気を写真に収める\n\n## 会場への到着時間\n\nチケットには「開場」と「開演」の2つの時間が書かれています。「開場」は会場に入れる時間、「開演」はライヴが始まる時間です。\n\n- **整理番号順の入場（スタンディング）の場合**\n  - 開場30分前には会場周辺にいると安心\n- **指定席の場合**\n  - 開場時間に合わせればOK\n- **グッズ購入をしたい場合**\n  - どうしても欲しいグッズがある場合は、事前に会場ごとのグッズ販売開始時間をチェックし、開始時間前に並ぶのがおすすめ\n\n## 終演後の過ごし方\n\n余韻に浸りながら、近くのお店で感想を語り合うのも楽しみのひとつ。\nお店によってはライヴ帰りのファンで混雑することもあるので、事前に予約しておくと安心です。\n各会場ページに周辺の飲食店情報もまとめていますので、ぜひチェックしてみてください。\n\n❗️ ライヴ後に耳鳴りや耳の違和感が続く場合は、早めに耳鼻科を受診しましょう。音響外傷は早期治療が大切です。心配な方は、上記の「あると便利」で紹介したライヴ用イヤープロテクターの使用をおすすめします。\n（最悪の場合は聴力を失うこともありますのでなるべく早く受診してください）\n\n---\n\n最高のライヴ体験になりますように！🎵\n",markdownFileEn:"Many of you may be attending a Reol live show for the first time on the Bijigaku Tour!\nHere's a guide with everything you need to know before going to a Reol concert.\nOf course, everyone enjoys live shows differently, so please take this article as a general reference.\n\n## What to Bring (For Entry)\n\n#### Essentials\n\n- 🎫 Ticket\n  - Save your phone battery since e-tickets are common\n- 💰 Cash\n  - For the drink ticket. Usually around 600 yen is required at entry\n  - Some venues don't accept cashless payments, so check in advance\n- 💧 Drinks\n  - You can exchange the drink ticket you receive at entry for a drink\n  - Essential since you'll get thirsty from cheering and sweating\n  - If you want to be at the very front, buy a drink beforehand and exchange your ticket after the show\n\n#### Nice to Have\n\n- 🔒 Small bag\n  - Something compact that won't get in the way\n- 🎤 Towel\n  - For wiping sweat. Reol's lives get as intense as a workout\n- 👂 Earplugs\n  - Live-specific ear protectors are recommended\n  - Recommended for those concerned about noise-induced hearing damage\n- 👟 Comfortable sneakers\n  - Especially important for standing shows\n\n#### Not Needed\n\n- 🧳 Large bags\n  - They won't fit in lockers and will bother people around you — leave them at your hotel\n- 🔋 Portable charger\n  - Fine if you're watching quietly, but too heavy for jumping around — put it in a locker\n\n## What to Wear\n\nFor standing shows, comfortable and easy-to-move-in clothing is the way to go. Hall shows are more relaxed, but here are some tips either way.\n\n- Avoid platform shoes or high heels\n  - Out of consideration for others and for your own safety\n  - Shorter attendees may opt for platforms, but be careful of injuries\n- Remove large accessories or hats\n  - They can block the view for people behind you\n- It tends to get hot inside venues\n  - Layered clothing that's easy to take off is ideal\n- Store your belongings in a coin locker to stay light\n  - Staff may ask you to put away large bags\n\n## Where to Stand\n\nFor standing shows, after entering in order of your ticket number, you can choose your spot freely — where you stand can completely change your experience. Whether you squeeze into a gap near the front or hang back, choose a spot that matches your style.\n\nSome venues may have structural elements like pillars that block visibility or affect sound, so checking the venue layout in advance is recommended.\n\n- **Front center area**\n  - Closest to the artist with an incredible sense of immersion\n  - Great for seeing Reol's facial expressions and subtle performance details\n  - Can get very crowded with pushing and jostling\n  - Experienced concertgoers may move into any open space, so if you don't want to give up your spot, close the gap or hold your ground (just talk it out... no fighting, please)\n  - Best for those with stamina\n- **Middle to back area**\n  - Relatively relaxed and comfortable\n  - Great view of the full stage production and lighting\n  - Recommended for first-time concertgoers\n- **Left/Right side areas**\n  - Usually less crowded, easier to get to the front even with a late entry number\n  - Great for watching band members up close\n  - Some angles may have limited stage visibility\n  - Be aware of being right in front of speakers where the volume can be very loud\n- **(If available) 2nd floor seating**\n  - Wide field of view overlooking the entire stage\n  - Often has better sound balance\n  - Further from the artist, so facial expressions and fine details may be harder to see\n\n## Coin Locker Information\n\nWe've compiled coin locker info on each venue's detail page. Live houses sometimes have lockers inside the venue. Hall shows may offer a cloak service. Checking coin lockers near the venue in advance is always a good idea.\n\n## Concert Etiquette\n\n- 📱 No photography or recording\n  - Unless officially announced otherwise\n- 🗣 Be considerate during MCs and quiet parts\n- 🎶 In Japan, singing along is generally considered rude unless the artist encourages it\n  - Some countries have a sing-along culture, so when in Rome, do as the Romans do\n- 🙋 Moshing and crowd surfing are generally prohibited\n- 🎒 Always put large bags in lockers\n- 🤝 Work together with fellow fans to create an enjoyable atmosphere\n\n## How to Enjoy the Show\n\nEveryone has their own way of enjoying a live show. Just have fun at your own pace, in your own way.\n\nHere are some ideas for reference:\n\n- 💡 As long as you're not bothering others, enjoy the show however you like! (No need to force yourself to match everyone else)\n- 🎤 Feel the unity with the artist\n- 🎶 Take in the stage production, lighting, and sound\n- 🕺 Get hyped with the fans around you\n- 📸 (If photography is allowed) Capture the atmosphere with photos of merch and the venue\n\n## When to Arrive\n\nYour ticket will show two times: \"Doors Open\" and \"Show Start.\" \"Doors Open\" is when you can enter the venue, and \"Show Start\" is when the performance begins.\n\n- **Numbered entry (standing shows)**\n  - Arrive near the venue about 30 minutes before doors open\n- **Reserved seating**\n  - Arriving at door time is fine\n- **If you want to buy merchandise**\n  - If there's a must-have item, check the merch sales start time for each venue in advance and line up before it begins\n\n## After the Show\n\nBasking in the afterglow and sharing your thoughts at a nearby restaurant is part of the fun.\nSome places may be crowded with fans after the show, so making a reservation in advance is a good idea.\nWe've included nearby restaurant information on each venue page, so be sure to check it out.\n\n❗️ If you experience ringing or discomfort in your ears after the show, see an ENT doctor as soon as possible. Noise-induced hearing damage requires early treatment. If you're concerned, we recommend using the live ear protectors mentioned in the \"Nice to Have\" section above.\n(In the worst case, you could lose your hearing, so please seek medical attention as soon as possible)\n\n---\n\nWishing you an amazing live experience! 🎵\n"},{slug:"venue-guide-overview",title:"連日参戦のすゝめ",titleEn:"Tips for Attending Multiple Shows",subtitle:"連日公演の攻略法、エリア別おすすめプラン、移動手段・予算の目安まで",subtitleEn:"Back-to-back show strategies, area-based plans, transport options & budget estimates",category:"venue-guide",tags:["遠征","プランニング","連日公演","予算"],tagsEn:["travel","planning","back-to-back","budget"],author:"美辞学ナビ編集部",authorEn:"Bijigaku Navi Editorial",publishedAt:"2026-02-19T00:00:00+09:00",emoji:"🧳",readingTime:8,sections:[],markdownFile:"美辞学ツアーは3月〜7月にかけて全国21都市を巡る大規模ツアー。複数公演への参戦を考えている方も多いはず。ここでは、効率よく遠征を楽しむためのプランニングのコツをまとめました。\n\n## 連日開催の公演\n\n美辞学ツアーには連日開催のセットが4組あります。近い会場同士なので、まとめて参戦するのがおすすめです。\n\n#### 🐻 北海道セット — 5/9 旭川 → 5/10 札幌\n\n[map:旭川→札幌 ルートマップ](https://www.google.com/maps?q=旭川駅+to+札幌駅&output=embed)\n\n- 旭川から札幌はJR特急で約1時間25分\n  - 終演後に移動すれば、札幌に当日中に着ける\n  - 車なら道央自動車道で約2時間。北海道はドライブ遠征も快適\n- 旭川で旭山動物園、札幌でジンギスカン＆夜景を楽しむ余裕も\n- 前泊含めて**2泊3日**がベスト\n  - 旭川空港 or 新千歳空港のどちらからでもアクセス可\n\n#### 🏔 甲信越セット — 5/23 長野 → 5/24 新潟\n\n[map:長野→新潟 ルートマップ](https://www.google.com/maps?q=長野駅+to+新潟駅&output=embed)\n\n- 長野から新潟は北陸新幹線で最速1時間10分程度\n  - ただし上越妙高乗り換えのルートになるので要注意\n  - 車なら上信越道→北陸道で約2時間半。途中の妙高SAからの景色が絶景\n- 善光寺参り → ライヴ → 翌日新潟で日本海の幸、という贅沢コースも\n\n#### ⛩ 京都・岐阜セット — 5/30 京都 → 5/31 岐阜\n\n[map:京都→岐阜 ルートマップ](https://www.google.com/maps?q=京都駅+to+岐阜駅&output=embed)\n\n- 京都から岐阜はJR東海道本線で約1時間40分\n  - 新幹線なら京都→名古屋→岐阜で約1時間\n  - 車なら名神高速経由で約1時間半。荷物の積み替え不要で楽\n- 京都観光を前後に組み込むなら前泊がおすすめ\n\n#### 🌋 九州セット — 4/18 長崎 → 4/19 熊本\n\n[map:長崎→熊本 ルートマップ](https://www.google.com/maps?q=長崎駅+to+熊本駅&output=embed)\n\n- 長崎から熊本は西九州新幹線＋在来線で約2時間半\n  - 高速バスなら約3時間半、料金は半額以下\n  - 車なら長崎道→九州道で約2時間。レンタカーなら途中の温泉に寄り道も\n- 長崎ちゃんぽん → 熊本馬刺しの最強グルメリレーが楽しめる\n\n## エリアまとめ遠征プラン\n\n連日でなくても、近い日程×近いエリアをまとめると効率的です。\n\n#### プランA：四国・中国地方まとめ（3月）\n\n- 3/20 徳島 → 3/22 周南（山口）\n  - 2日空くので徳島で1泊して観光、翌日移動もあり\n  - 徳島→周南は在来線乗り継ぎで約4〜5時間\n  - 車なら瀬戸大橋→山陽道経由で約4時間。しまなみ海道ルートもおすすめ\n\n#### プランB：九州セット（4月）\n\n- 4/18 長崎 → 4/19 熊本\n  - 連日なので**2泊3日**でまとめるのが効率的\n  - 車なら九州内の移動が自由自在。長崎→熊本は約2時間\n- 沖縄（4/29）は10日空くので別の遠征として計画するのがおすすめ\n\n#### プランC：中部周遊（5月末）\n\n- 5/23 長野 → 5/24 新潟 → 5/30 京都 → 5/31 岐阜\n  - 4公演を2回の遠征に分けるか、1週間通しで回るか\n  - 通しなら間の平日に観光を挟んで充実の旅に\n  - 車で通し周遊なら荷物の心配なし。4会場分の着替えも積みっぱなしでOK\n\n#### プランD：ホール公演まとめ打ち（6〜7月）\n\n- 6/12 仙台 → 6/19 大阪 → 6/27 福岡 → 7/4 名古屋 → 7/10 東京\n  - 後半はホール公演が続くので、好きな組み合わせで\n  - 東京ファイナルは外せないとして、もう1〜2公演をセットに\n  - 名古屋→東京は車で約3時間半。近い公演をセットにすれば車も選択肢\n\n## 移動手段の選び方\n\n遠征の移動手段は距離と予算で使い分けましょう。\n\n#### ✈️ 飛行機\n\n- **おすすめ区間**\n  - 沖縄、北海道（旭川・札幌）、九州（長崎・熊本・福岡）\n- 早割で予約すれば片道1万円以下も\n- LCC利用なら成田・関空発着が中心\n  - 空港から会場までの移動時間も計算に入れること\n\n#### 🚄 新幹線\n\n- **おすすめ区間**\n  - 東京起点：宇都宮、仙台、長野、新潟、名古屋、京都、大阪\n  - 大阪起点：神戸、岡山方面、福岡\n- EX予約やスマートEXで割引あり\n- 時間の確実性が高く、終演後でも移動しやすい\n\n#### 🚌 高速バス\n\n- **おすすめ区間**\n  - 東京↔仙台、東京↔長野、大阪↔名古屋、福岡↔長崎・熊本\n- 夜行バスなら宿泊費も節約できる\n  - ただしライヴ後の夜行は体力的にハード。翌日公演がなければアリ\n- 3列独立シートを選ぶと快適度が段違い\n\n#### 🚗 車\n\n- グループ遠征なら割り勘で最安になることも\n- 駐車場の事前確認は必須\n  - 各会場の詳細ページに駐車場情報をまとめています\n- 長距離の場合は高速代＋ガソリン代を計算してから判断を\n\n## 予算の目安\n\n複数公演に参戦する場合の1公演あたりの目安です。\n\n#### 日帰り遠征（新幹線圏内）\n\n- 交通費：5,000〜15,000円\n- 食事代：2,000〜3,000円\n- **合計：7,000〜18,000円**＋チケット代\n\n#### 1泊遠征（新幹線 or 飛行機）\n\n- 交通費：10,000〜30,000円\n- 宿泊費：5,000〜10,000円\n  - カプセルホテルなら3,000円台もあり\n- 食事代：3,000〜5,000円\n- **合計：18,000〜45,000円**＋チケット代\n\n#### 2泊以上の遠征（連日公演セット）\n\n- 交通費：15,000〜40,000円\n- 宿泊費：10,000〜20,000円\n- 食事代：5,000〜10,000円\n- **合計：30,000〜70,000円**＋チケット代\n\n### 節約のコツ\n\n- **早割航空券**は発売直後に押さえる\n- **ホテルの早期予約**でビジネスホテルを確保\n  - ツアー発表後はファンで埋まりがち\n- **夜行バス**は宿泊費と交通費を同時に節約できる裏ワザ\n- **連日公演のセット**で1回の遠征費で2公演楽しめる\n\n## スケジュールの立て方\n\n#### 日帰りの場合\n\n- 開演3時間前に現地着を目安にする\n  - 会場周辺の下見、コインロッカーの確保、食事を済ませる余裕ができる\n- 終演後の最終交通手段は必ず事前確認\n  - 地方会場は最終電車が早いので要注意\n\n#### 宿泊ありの場合\n\n- **会場近くのホテルを取るとコインロッカーが不要になる**\n  - チェックイン後に荷物を置いて身軽に会場へ行ける\n  - コインロッカー探しの手間と数百円の出費もカット\n  - 終演後もすぐホテルに戻れるので、地方の終電を気にしなくていい\n- 翌日に観光を入れるなら、チェックアウト後にコインロッカーを使う\n- 帰りの交通は昼過ぎの便にしておくとゆとりが持てる\n\n---\n\n各会場の詳しいアクセス・周辺施設は、美辞学ナビのタイムラインから会場名をタップしてご覧ください。遠征グルメ情報は「遠征グルメマップ」コラムもあわせてどうぞ！🧳\n",markdownFileEn:"The Bijigaku Tour spans 21 cities across Japan from March to July. Many fans are planning to attend multiple shows. Here are some tips for planning your tour trips efficiently.\n\n## Back-to-Back Shows\n\nThe Bijigaku Tour has 4 pairs of consecutive shows at nearby venues. Attending both is highly recommended.\n\n#### 🐻 Hokkaido Set — 5/9 Asahikawa → 5/10 Sapporo\n\n[map:Asahikawa → Sapporo Route](https://www.google.com/maps?q=Asahikawa+Station+to+Sapporo+Station&output=embed)\n\n- Asahikawa to Sapporo is about 1 hour 25 minutes by JR limited express\n  - You can move after the show and arrive in Sapporo the same day\n  - By car, it's about 2 hours via the Dōō Expressway. Hokkaido is great for road trips\n- Plenty of time to enjoy Asahiyama Zoo in Asahikawa and Genghis Khan BBQ & night views in Sapporo\n- **2 nights / 3 days** including the night before is ideal\n  - Accessible from either Asahikawa Airport or New Chitose Airport\n\n#### 🏔 Kōshinetsu Set — 5/23 Nagano → 5/24 Niigata\n\n[map:Nagano → Niigata Route](https://www.google.com/maps?q=Nagano+Station+to+Niigata+Station&output=embed)\n\n- Nagano to Niigata is about 1 hour 10 minutes by Hokuriku Shinkansen\n  - Note: you may need to transfer at Jōetsumyōkō Station\n  - By car, about 2.5 hours via the Jōshinetsu and Hokuriku Expressways. The view from Myōkō SA is stunning\n- A luxurious course: visit Zenkō-ji Temple → live show → fresh seafood from the Sea of Japan the next day\n\n#### ⛩ Kyoto & Gifu Set — 5/30 Kyoto → 5/31 Gifu\n\n[map:Kyoto → Gifu Route](https://www.google.com/maps?q=Kyoto+Station+to+Gifu+Station&output=embed)\n\n- Kyoto to Gifu is about 1 hour 40 minutes by JR Tōkaidō Line\n  - About 1 hour via Shinkansen (Kyoto → Nagoya → Gifu)\n  - By car, about 1.5 hours via the Meishin Expressway — no need to repack your luggage\n- Staying the night before is recommended if you want to explore Kyoto\n\n#### 🌋 Kyushu Set — 4/18 Nagasaki → 4/19 Kumamoto\n\n[map:Nagasaki → Kumamoto Route](https://www.google.com/maps?q=Nagasaki+Station+to+Kumamoto+Station&output=embed)\n\n- Nagasaki to Kumamoto is about 2.5 hours via Nishi-Kyushu Shinkansen + local train\n  - Highway bus is about 3.5 hours at less than half the price\n  - By car, about 2 hours via the Nagasaki and Kyushu Expressways. Consider a hot spring detour with a rental car\n- Enjoy the ultimate gourmet relay: Nagasaki champon → Kumamoto horse sashimi\n\n## Area-Based Trip Plans\n\nEven for non-consecutive shows, grouping nearby dates and areas together is efficient.\n\n#### Plan A: Shikoku & Chūgoku Region (March)\n\n- 3/20 Tokushima → 3/22 Shūnan (Yamaguchi)\n  - 2 days in between — stay in Tokushima for sightseeing, then travel the next day\n  - Tokushima to Shūnan is about 4–5 hours by local trains\n  - By car, about 4 hours via the Seto Ōhashi Bridge and Sanyō Expressway. The Shimanami Kaidō route is also recommended\n\n#### Plan B: Kyushu Set (April)\n\n- 4/18 Nagasaki → 4/19 Kumamoto\n  - Back-to-back shows — **2 nights / 3 days** is the most efficient\n  - By car, you have total freedom to move around Kyushu. Nagasaki to Kumamoto is about 2 hours\n- Okinawa (4/29) is 10 days later, so plan it as a separate trip\n\n#### Plan C: Chūbu Circuit (Late May)\n\n- 5/23 Nagano → 5/24 Niigata → 5/30 Kyoto → 5/31 Gifu\n  - Split into 2 trips, or do all 4 shows in one week-long journey\n  - For the full circuit, fill the weekdays in between with sightseeing\n  - By car, no luggage worries for the whole trip — just leave outfits for all 4 venues in the trunk\n\n#### Plan D: Hall Shows Marathon (June–July)\n\n- 6/12 Sendai → 6/19 Osaka → 6/27 Fukuoka → 7/4 Nagoya → 7/10 Tokyo\n  - The second half is all hall shows — pick your favorite combinations\n  - The Tokyo finale is a must — pair it with 1–2 more shows\n  - Nagoya to Tokyo is about 3.5 hours by car — a viable option for nearby shows\n\n## Choosing Your Transport\n\nPick your transport based on distance and budget.\n\n#### ✈️ Flights\n\n- **Recommended routes**\n  - Okinawa, Hokkaido (Asahikawa & Sapporo), Kyushu (Nagasaki, Kumamoto, Fukuoka)\n- Early-bird fares can be under ¥10,000 one way\n- LCCs mainly depart from Narita and Kansai airports\n  - Factor in travel time from the airport to the venue\n\n#### 🚄 Shinkansen (Bullet Train)\n\n- **Recommended routes**\n  - From Tokyo: Utsunomiya, Sendai, Nagano, Niigata, Nagoya, Kyoto, Osaka\n  - From Osaka: Kobe, Okayama area, Fukuoka\n- Discounts available through EX-IC and Smart EX\n- Highly reliable timing — easy to travel even after the show ends\n\n#### 🚌 Highway Bus\n\n- **Recommended routes**\n  - Tokyo ↔ Sendai, Tokyo ↔ Nagano, Osaka ↔ Nagoya, Fukuoka ↔ Nagasaki/Kumamoto\n- Overnight buses save on accommodation costs\n  - However, taking an overnight bus after a live show is physically demanding — only if there's no show the next day\n- 3-row independent seats make a huge difference in comfort\n\n#### 🚗 Car\n\n- Group trips can be the cheapest option when splitting costs\n- Always check parking availability in advance\n  - Parking info is listed on each venue's detail page\n- For long distances, calculate highway tolls + gas costs before deciding\n\n## Budget Estimates\n\nRough per-show costs when attending multiple shows.\n\n#### Day Trip (Shinkansen Range)\n\n- Transport: ¥5,000–15,000\n- Meals: ¥2,000–3,000\n- **Total: ¥7,000–18,000** + ticket price\n\n#### 1-Night Trip (Shinkansen or Flight)\n\n- Transport: ¥10,000–30,000\n- Accommodation: ¥5,000–10,000\n  - Capsule hotels can be as low as ¥3,000\n- Meals: ¥3,000–5,000\n- **Total: ¥18,000–45,000** + ticket price\n\n#### 2+ Night Trip (Back-to-Back Show Sets)\n\n- Transport: ¥15,000–40,000\n- Accommodation: ¥10,000–20,000\n- Meals: ¥5,000–10,000\n- **Total: ¥30,000–70,000** + ticket price\n\n### Money-Saving Tips\n\n- **Book early-bird flights** as soon as they go on sale\n- **Reserve hotels early** to secure business hotels\n  - They tend to fill up quickly after the tour is announced\n- **Overnight buses** save on both transport and accommodation\n- **Back-to-back show sets** let you enjoy 2 shows for the cost of 1 trip\n\n## Planning Your Schedule\n\n#### Day Trips\n\n- Aim to arrive 3 hours before the show starts\n  - This gives you time to scout the venue area, secure a coin locker, and eat\n- Always check the last train/bus after the show\n  - Rural venues often have early last trains\n\n#### Overnight Stays\n\n- **Booking a hotel near the venue eliminates the need for coin lockers**\n  - Check in, drop off your bags, and head to the venue hands-free\n  - Save the hassle and cost of finding a coin locker\n  - You can head straight back to the hotel after the show — no need to worry about the last train\n- If sightseeing the next day, use a coin locker after checkout\n- Book a mid-afternoon return trip so you're not rushed\n\n---\n\nFor detailed access info and nearby facilities, tap a venue name on the Bijigaku Navi timeline. Also check out the \"Tour Food Guide\" column for local cuisine recommendations! 🧳\n"}].map((function(n){const e=Object.assign({},n);return e.markdownFile&&(e.sections=t(e.markdownFile)),e.markdownFileEn&&(e.sectionsEn=t(e.markdownFileEn)),e})),s=n=>i.find((e=>e.slug===n))}}]);
